/**
 * Benjamin's Cup
 * --------------
 * Joseph plants his silver cup in Benjamin's sack, and offers to keep the thief as his slave. Stage: a grain hall at dawn, a steward with a cup, the brothers returning in fear, a cup found in the youngest's sack; a test of love for the father's son.
 *
 * Palette 0x1a0e08 → 0x060402 · light: dusk · hero: cup
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./joseph-kit.js.
 */

import { THREE, createScene, wheat, cup, person } from './joseph-kit.js';

const BG = 0x1a0e08;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 1593770221, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* fields: standing grain to the horizon */
    wheat(W, group, 0, 34, 220, 110, { h: 2.1, stalk: 0x1d0f09, head: 0x21120a });

    /* hero: the cup */
    cup(W, group, 0, 1.0, 0, 1.4, { gold: 0x100805 });
    W.disc([0, 3.5, -10], 3, 0x22120a, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x1a0e08, ry: 0.23, s: 1.09 });
    person(W, group, [4.5, 0, 6], { robe: 0x060402, ry: -0.36, s: 1.18 });

    return W.finish();
}

export default { build };
